export async function resolveAuthenticationAuthority(strategy: string, subject: string, principalKind = "user"): Promise<unknown[]> {
  switch (`${strategy}:${principalKind}`) {
    case "browser_session:user": return (await authenticationRows("SELECT \"id\", \"authentication_subject\", \"status\", \"disabled_at\" FROM \"user\" WHERE \"authentication_subject\" = $1 LIMIT 2", [subject])).map(row => ({
      id: row["id"],
      authentication_subject: row["authentication_subject"],
      status: row["status"],
      disabled_at: row["disabled_at"],
    }));
    case "api_bearer:user": return (await authenticationRows("SELECT \"id\", \"authentication_subject\", \"status\", \"disabled_at\" FROM \"user\" WHERE \"authentication_subject\" = $1 LIMIT 2", [subject])).map(row => ({
      id: row["id"],
      authentication_subject: row["authentication_subject"],
      status: row["status"],
      disabled_at: row["disabled_at"],
    }));
    case "api_bearer:service": return (await authenticationRows("SELECT \"id\", \"owner_id\", \"name\", \"status\", \"created_at\", \"disabled_at\" FROM \"service\" WHERE \"name\" = $1 LIMIT 2", [subject])).map(row => ({
      id: row["id"],
      owner_id: row["owner_id"],
      name: row["name"],
      status: row["status"],
      created_at: row["created_at"],
      disabled_at: row["disabled_at"],
    }));
    default: throw new Error("Unsupported authentication authority");
  }
}
